8	/**
9	 * The one primary action on item detail (Fitcheck.dc.html:654).
10	 *
11	 * The outcome is a STATE, not an exception: "this is a Pro feature" and "there
12	 * is not enough else in your closet yet" are both real answers, and a thrown
13	 * error would render as a dead button with no explanation.
14	 *
15	 * The button stays VISIBLE and enabled for free users on purpose. Nobody buys a
16	 * feature they have never seen, and this screen — the canonical one — is where
17	 * the want is felt. Tapping it explains the feature rather than doing nothing.
18	 */
19	export function StyleCta({ itemId }: { itemId: string }) {
20	  const router = useRouter();
21	  const [pending, start] = useTransition();
22	  const [message, setMessage] = useState<string | null>(null);
23	  // A Pro gate and "your closet is too thin for this yet" are different answers
24	  // and get different weight: the first is a sheet that explains and sells, the
25	  // second is a quiet line, because there is nothing to buy — you add a piece.
26	  const [upgrade, setUpgrade] = useState<string | null>(null);
27	  // Only offered once a set exists. "Try another" before there IS another is a
28	  // control with nothing to compare against.
29	  const [styled, setStyled] = useState(false);
30	
31	  function run(regenerate: boolean) {
32	    start(async () => {
33	      setMessage(null);
34	      setUpgrade(null);
35	      const res = await styleWithItem(itemId, { regenerate });
36	      if (res.status === "ok") {
37	        setStyled(true);
38	        router.push(`/outfits/${res.outfitIds[0]}`);
39	      }
40	      // The reason is rendered verbatim, never re-worded here. It used to read
41	      // "that's today's stylings used — back tomorrow", written when styling
42	      // was assumed to share the daily generation allowance. It is a Pro
43	      // capability, so tomorrow gives a free user no more of them — the old
44	      // copy told people to wait for something that would never arrive.
45	      else if (res.status === "limited") setUpgrade(res.message);
46	      else setMessage(res.message);
47	    });
48	  }
49	
50	  return (
51	    <div className="flex flex-1 flex-col">
52	      <button
53	        type="button"
54	        disabled={pending}
55	        onClick={() => run(false)}
56	        className="min-h-[54px] w-full rounded-[14px] bg-foreground text-[15.5px] font-semibold text-canvas disabled:opacity-70"
57	      >
58	        {pending ? "Styling…" : "Style an outfit with this"}
59	      </button>
60	
61	      {/* A bounded secondary with WORDS, below the primary — the shape PR #20
62	          arrived at after an icon-only Regenerate was tried and rejected,
63	          because nothing tells you a ⟳ means "spend an AI call". It exists
64	          because the cache is right but silent: tapping again returned the
65	          identical look with no explanation. */}
66	      {styled && (
67	        <button
68	          type="button"
69	          disabled={pending}
70	          onClick={() => run(true)}
71	          className="mx-auto mt-2 min-h-[44px] rounded-full px-4 text-[13px] text-muted-foreground shadow-[inset_0_0_0_1px_var(--hairline-4)] disabled:opacity-60"
72	        >
73	          {pending ? "Styling…" : "Try another look"}
74	        </button>
75	      )}
76	
77	      {message && (
78	        <p role="status" className="mt-2 text-center text-xs text-muted-foreground">
79	          {message}
80	        </p>
81	      )}
82	
83	      <UpgradeSheet
84	        open={Boolean(upgrade)}
85	        title="Style a look around any piece"
86	        body={upgrade ?? ""}
87	        onClose={() => setUpgrade(null)}
88	      />
89	    </div>
90	  );
91	}
