86	  const supabase = await createClient();
87	  const { count } = await supabase
88	    .from("items")
89	    .select("id", { count: "exact", head: true })
90	    .eq("archived", false);
91	
92	  const check = checkCloset(e, count ?? 0);
93	  if (!check.allowed) throw new UploadLimitError(check.reason);
94	}
